package com.jadhavr.erp.email.service;import com.jadhavr.erp.common.dto.PageResponse;import com.jadhavr.erp.common.exception.ResourceNotFoundException;import com.jadhavr.erp.email.dto.EmailNotificationResponse;import com.jadhavr.erp.email.entity.EmailNotification;import com.jadhavr.erp.email.enums.*;import com.jadhavr.erp.email.repository.EmailNotificationRepository;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.Locale;
@Service public class EmailAdminService{private final EmailNotificationRepository repo;public EmailAdminService(EmailNotificationRepository r){repo=r;}public PageResponse<EmailNotificationResponse>search(EmailStatus status,EmailType type,String recipient,int page,int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");Specification<EmailNotification>s=Specification.where(null);if(status!=null)s=s.and((r,q,b)->b.equal(r.get("status"),status));if(type!=null)s=s.and((r,q,b)->b.equal(r.get("emailType"),type));if(recipient!=null&&!recipient.isBlank()){String p="%"+recipient.toLowerCase(Locale.ROOT)+"%";s=s.and((r,q,b)->b.like(b.lower(r.get("recipientEmail")),p));}return PageResponse.from(repo.findAll(s,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"))).map(this::map));}public EmailNotificationResponse get(Long id){return map(find(id));}@Transactional public EmailNotificationResponse retry(Long id){EmailNotification n=find(id);if(n.getStatus()==EmailStatus.SENT||n.getStatus()==EmailStatus.CANCELLED)throw new IllegalArgumentException("Notification cannot be retried");n.setStatus(EmailStatus.QUEUED);n.setNextRetryAt(null);n.setFailureReason(null);return map(repo.save(n));}@Transactional public EmailNotificationResponse cancel(Long id){EmailNotification n=find(id);if(n.getStatus()==EmailStatus.SENT)throw new IllegalArgumentException("Sent notification cannot be cancelled");n.setStatus(EmailStatus.CANCELLED);return map(repo.save(n));}private EmailNotification find(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Email notification not found"));}private EmailNotificationResponse map(EmailNotification n){String e=n.getRecipientEmail();int at=e.indexOf('@');String masked=at>1?e.charAt(0)+"***"+e.substring(at):"***";return new EmailNotificationResponse(n.getId(),masked,n.getRecipientName(),n.getEmailType(),n.getSubject(),n.getStatus(),n.getPriority(),n.getRetryCount(),n.getMaxRetries(),n.getProvider(),n.getFailureReason(),n.getCreatedAt(),n.getSentAt(),n.getCorrelationId());}}
